std::vector<int> data = {1, 2, 3, 4, 5};

// 1. Iteration by value (copy)
for (int val : data) {
    // Read access
}

// 2. Iteration by reference (modification)
for (int& ref : data) {
    ref *= 2;
}

// 3. Using const auto& (efficient read-only)
std::map<int, float> scores;
for (const auto& item : scores) {
    // Access item.first, item.second
}

// 4. Works on raw arrays
int arr[] = {10, 20, 30};
for (int x : arr) {}
